let shade;

function preload() {
  shade = createShader(vert, frag)
}
function setup() {
  createCanvas(800, 800, WEBGL);
  // noStroke();
}

function draw() {
	background(255);
  shade.setUniform("u_mouse", [
    (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width,
    map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0.0, height, height, 0.0) / height,
  ]);
  shade.setUniform("u_time", millis() / 1000.0);
  shade.setUniform("u_resolution", [width, height]);

  shader(shade);
  rect(0, 0, width, height);
}

const vert = `
#ifdef GL_ES
precision mediump float;
#endif

attribute vec3 aPosition;

void main() {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  gl_Position = positionVec4;
}
`
const frag = `
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;

void main() {
  vec2 st = gl_FragCoord.xy/u_resolution.xy;
  float dist = distance(st, u_mouse);
  dist = abs(sin(dist + u_time));
  gl_FragColor = vec4(st.x,st.y, dist,dist); // R,G,B,A

}
`

